// Idempotency key pattern — safe retries in distributed systems
const crypto = require('crypto');

// Client generates a unique key per logical operation
function createOrder(cartId, paymentToken) {
  const idempotencyKey = crypto
    .createHash('sha256')
    .update(`order:${cartId}:${paymentToken}`)
    .digest('hex');

  return fetch('/api/orders', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Idempotency-Key': idempotencyKey  // server deduplicates on this
    },
    body: JSON.stringify({ cartId, paymentToken })
  });
}

// Server-side: idempotent handler
const processedRequests = new Map(); // in production: Redis or DB table

async function handleCreateOrder(req, res) {
  const key = req.headers['idempotency-key'];

  // Return cached response if already processed
  if (processedRequests.has(key)) {
    return res.json(processedRequests.get(key));
  }

  const order = await db.createOrder(req.body);
  const response = { orderId: order.id, status: 'created' };

  // Cache response before returning (TTL: 24h in production)
  processedRequests.set(key, response);

  res.status(201).json(response);
}

// Distributed systems failure taxonomy

// 1. Crash-stop: node halts, never recovers
//    Detection: timeout + heartbeat absence
//    Mitigation: replication, automatic failover

// 2. Crash-recovery: node crashes, restarts with disk state
//    Challenge: in-flight operations lost from memory
//    Mitigation: write-ahead logs, idempotent replay

// 3. Omission: messages dropped (network unreliable)
//    Detection: timeout + sequence numbers
//    Mitigation: retry with exponential backoff + jitter

// 4. Byzantine: node sends arbitrary wrong responses
//    Detection: requires quorum agreement (3f+1 nodes for f faults)
//    Mitigation: PBFT, Tendermint (expensive — rarely used in internal systems)

// Retry with exponential backoff + jitter
async function retryWithBackoff(fn, maxAttempts = 5) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      const base = Math.min(1000 * 2 ** attempt, 30000);
      const jitter = Math.random() * base * 0.3;
      await new Promise(r => setTimeout(r, base + jitter));
    }
  }
}
